package org.crux.data.ai

import org.crux.ui.model.ClickContext
import org.crux.ui.model.UiTimelineV2
import kotlin.time.Clock
import kotlin.time.Instant

/**
 * Structured on-device feed digest generated by Gemma 4 Edge.
 */
public data class FeedDigest(
    val title: String,
    val subtitle: String,
    val topTopics: List<String>,
    val highlights: List<DigestHighlight>,
    val postCount: Int,
    val generatedAt: Instant,
)

/**
 * An individual topic highlight within the Catch Me Up digest.
 */
public data class DigestHighlight(
    val topic: String,
    val summary: String,
    val authorName: String? = null,
    val authorHandle: String? = null,
    val authorAvatar: String? = null,
    val engagementInfo: String? = null,
    val platformId: String? = null,
    val onClick: ((ClickContext) -> Unit)? = null,
)

